import React, { useState } from 'react';
import Header from '../components/common/Header';
import Footer from '../components/common/Footer';
import { useAuth } from '../contexts/AuthContext';
import { useCoupon } from '../hooks/useCoupon';
import { Gift, Percent, Truck, Calendar, CheckCircle, Plus, X } from 'lucide-react';
import '../styles/CouponBoxPage.css';

const CouponBoxPage = () => {
  const { user } = useAuth();
  const { userCoupons, issueCoupon } = useCoupon(user);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [couponCode, setCouponCode] = useState('');
  const [message, setMessage] = useState('');

  // 사용자 쿠폰들
  const coupons = userCoupons || [];

  const getCouponIcon = (type) => {
    switch (type) {
      case 'percentage':
        return <Percent size={20} />;
      case 'fixed':
        return <Gift size={20} />;
      case 'shipping':
        return <Truck size={20} />;
      default:
        return <Gift size={20} />;
    }
  };

  const getCouponTypeText = (type) => {
    switch (type) {
      case 'percentage':
        return '퍼센트 할인';
      case 'fixed':
        return '금액 할인';
      case 'shipping':
        return '배송비 할인';
      default:
        return '일반 할인';
    }
  };

  const formatDiscount = (coupon) => {
    if (coupon.type === 'percentage') {
      return `${coupon.value}% 할인`;
    } else if (coupon.type === 'fixed') {
      return `${coupon.value.toLocaleString()}원 할인`;
    } else if (coupon.type === 'shipping') {
      return '무료배송';
    }
    return '할인';
  };

  // 쿠폰 등록 함수
  const handleCouponRegistration = () => {
    if (!couponCode.trim()) {
      setMessage('쿠폰 번호를 입력해주세요.');
      return;
    }

    // 쿠폰 번호 검증 및 등록 로직
    const result = registerCouponByCode(couponCode.trim().toUpperCase());

    if (result.success) {
      setMessage(result.message);
      setCouponCode('');
      setTimeout(() => {
        setIsModalOpen(false);
        setMessage('');
      }, 2000);
    } else {
      setMessage(result.message);
    }
  };

  // 쿠폰 번호로 쿠폰 등록하는 함수 (취약점 포함)
  const registerCouponByCode = (code) => {
    // 기본 쿠폰 코드들
    const validCodes = {
      'WELCOME20': 'WELCOME20',
      'FREESHIP': 'FREESHIP', 
      'FIXED5000': 'FIXED5000',
      'PLUSH30': 'PLUSH30',
      'BIRTHDAY50': 'BIRTHDAY50',
      // 취약점: 특별한 마스터 코드들 (무제한 사용 가능)
      'MASTER99': 'MASTER99', // 99% 할인 무제한
      'UNLIMITED': 'UNLIMITED', // 무제한 사용 쿠폰
      'ADMIN2024': 'ADMIN2024', // 관리자용 쿠폰
      'KIRBYLOVE': 'KIRBYLOVE', // 특별 이벤트 쿠폰
    };

    // 취약점 1: 간단한 패턴 매칭으로 쿠폰 생성 가능
    if (code.startsWith('KIRBY') && code.length >= 8) {
      const customCoupon = {
        id: code,
        name: `커스텀 쿠폰 ${code}`,
        description: '특별 제작 쿠폰',
        type: 'percentage',
        value: 25,
        minOrderAmount: 0,
        maxDiscountAmount: 999999,
        validFrom: '2024-01-01',
        validUntil: '2030-12-31', // 취약점: 매우 긴 유효기간
        isActive: true,
        usageLimit: 999, // 취약점: 매우 높은 사용 횟수
        categoryRestrictions: [],
        productRestrictions: [],
        newMemberOnly: false,
        icon: '🎁'
      };

      const result = issueCoupon(code);
      if (result.success) {
        return { success: true, message: `커스텀 쿠폰 ${code}이 등록되었습니다!` };
      }
    }

    // 취약점 2: 특정 패턴으로 무제한 쿠폰 생성
    if (code.includes('UNLIMITED') || code.includes('MASTER')) {
      const unlimitedCoupon = {
        id: code,
        name: `무제한 쿠폰 ${code}`,
        description: '무제한 사용 가능한 특별 쿠폰',
        type: 'percentage',
        value: code.includes('MASTER') ? 99 : 50,
        minOrderAmount: 0,
        maxDiscountAmount: 999999,
        validFrom: '2024-01-01',
        validUntil: '2099-12-31', // 취약점: 거의 무제한 유효기간
        isActive: true,
        usageLimit: 999999, // 취약점: 거의 무제한 사용 횟수
        categoryRestrictions: [],
        productRestrictions: [],
        newMemberOnly: false,
        icon: '💎'
      };

      const result = issueCoupon(code);
      if (result.success) {
        return { success: true, message: `무제한 쿠폰 ${code}이 등록되었습니다!` };
      }
    }

    // 일반 쿠폰 코드 처리
    if (validCodes[code]) {
      const result = issueCoupon(validCodes[code]);
      return result;
    }

    // 취약점 3: 숫자만으로도 쿠폰 생성 가능
    if (/^\d+$/.test(code) && code.length >= 6) {
      const numericCoupon = {
        id: `NUM${code}`,
        name: `숫자 쿠폰 ${code}`,
        description: '숫자 패턴 쿠폰',
        type: 'fixed',
        value: parseInt(code.slice(-4)) || 1000, // 마지막 4자리를 할인 금액으로 사용
        minOrderAmount: 0,
        maxDiscountAmount: 50000,
        validFrom: '2024-01-01',
        validUntil: '2025-12-31',
        isActive: true,
        usageLimit: 10,
        categoryRestrictions: [],
        productRestrictions: [],
        newMemberOnly: false,
        icon: '🔢'
      };

      const result = issueCoupon(`NUM${code}`);
      if (result.success) {
        return { success: true, message: `숫자 쿠폰 NUM${code}이 등록되었습니다!` };
      }
    }

    return { success: false, message: '유효하지 않은 쿠폰 번호입니다.' };
  };

  return (
    <>
      <Header />
      <div className="coupon-page-container">
        <div className="coupon-page-content">
          <div className="coupon-header">
            <h2 className="coupon-title">
              <Gift size={24} />
              쿠폰함
            </h2>
            <p className="coupon-subtitle">
              보유하신 쿠폰을 확인하고 사용하세요
            </p>
            <button 
              className="coupon-register-btn"
              onClick={() => setIsModalOpen(true)}
            >
              <Plus size={20} />
              쿠폰 등록
            </button>
          </div>

          {coupons.length === 0 ? (
            <div className="empty-coupon">
              <Gift size={48} className="empty-icon" />
              <h3>보유한 쿠폰이 없습니다</h3>
              <p>새로운 쿠폰을 받으려면 이벤트에 참여해보세요!</p>
            </div>
          ) : (
            <div className="coupon-stats">
              <div className="stat-item">
                <span className="stat-label">보유 쿠폰</span>
                <span className="stat-value">{coupons.length}개</span>
              </div>
              <div className="stat-item">
                <span className="stat-label">사용 가능</span>
                <span className="stat-value">{coupons.filter(c => !c.isUsed).length}개</span>
              </div>
            </div>
          )}

          <div className="coupon-grid">
            {coupons.map((coupon) => (
              <div 
                key={coupon.id} 
                className={`coupon-card ${coupon.isUsed ? 'used' : 'active'}`}
              >
                <div className="coupon-header-card">
                  <div className="coupon-icon">
                    {getCouponIcon(coupon.type)}
                  </div>
                  <div className="coupon-info">
                    <h3 className="coupon-name">{coupon.name}</h3>
                    <span className="coupon-type">{getCouponTypeText(coupon.type)}</span>
                  </div>
                  {coupon.isUsed && (
                    <div className="used-badge">
                      <CheckCircle size={16} />
                      사용완료
                    </div>
                  )}
                </div>

                <div className="coupon-discount">
                  {formatDiscount(coupon)}
                </div>

                <div className="coupon-details">
                  <div className="detail-item">
                    <Calendar size={14} />
                    <span>유효기간: {coupon.validUntil}</span>
                  </div>
                  {coupon.minAmount > 0 && (
                    <div className="detail-item">
                      <span>최소 주문금액: {coupon.minAmount.toLocaleString()}원</span>
                    </div>
                  )}
                  {coupon.maxDiscount > 0 && (
                    <div className="detail-item">
                      <span>최대 할인: {coupon.maxDiscount.toLocaleString()}원</span>
                    </div>
                  )}
                </div>

                <div className="coupon-status">
                  {coupon.isUsed ? (
                    <span className="status-used">사용 완료</span>
                  ) : (
                    <span className="status-available">사용 가능</span>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* 쿠폰 등록 모달 */}
      {isModalOpen && (
        <div className="coupon-modal-overlay" onClick={() => setIsModalOpen(false)}>
          <div className="coupon-modal" onClick={(e) => e.stopPropagation()}>
            <div className="coupon-modal-header">
              <h3>쿠폰 등록</h3>
              <button 
                className="modal-close-btn"
                onClick={() => setIsModalOpen(false)}
              >
                <X size={20} />
              </button>
            </div>

            <div className="coupon-modal-body">
              <div className="input-group">
                <label htmlFor="couponCode">쿠폰 번호</label>
                <input
                  id="couponCode"
                  type="text"
                  value={couponCode}
                  onChange={(e) => setCouponCode(e.target.value)}
                  placeholder="쿠폰 번호를 입력하세요"
                  className="coupon-input"
                  maxLength={20}
                />
              </div>

              {message && (
                <div className={`message ${message.includes('등록되었습니다') ? 'success' : 'error'}`}>
                  {message}
                </div>
              )}

              <div className="coupon-hints">
                <h4>💡 쿠폰 번호 힌트</h4>
                <ul>
                  <li><strong>일반 쿠폰:</strong> WELCOME20, FREESHIP, FIXED5000</li>
                  <li><strong>특별 쿠폰:</strong> KIRBY로 시작하는 8자리 이상</li>
                  <li><strong>숫자 쿠폰:</strong> 6자리 이상 숫자</li>
                  <li><strong>마스터 쿠폰:</strong> MASTER, UNLIMITED 포함</li>
                </ul>
              </div>
            </div>

            <div className="coupon-modal-footer">
              <button 
                className="cancel-btn"
                onClick={() => setIsModalOpen(false)}
              >
                취소
              </button>
              <button 
                className="register-btn"
                onClick={handleCouponRegistration}
                disabled={!couponCode.trim()}
              >
                등록하기
              </button>
            </div>
          </div>
        </div>
      )}

      <Footer />
    </>
  );
};

export default CouponBoxPage;
